","const API_BASE = "/api/now/table";

function getHeaders(): Record<string, string> {
 return {
 Accept: "application/json",
 "Content-Type": "application/json",
 "X-UserToken": (window as any).g_ck || "",
 };
}

export async function fetchAccounts(): Promise<any[]> {
 const params = new URLSearchParams({
 sysparm_display_value: "all",
 sysparm_fields: "sys_id,number,account_type,holder,balance,active",
 sysparm_limit: "50",
 });
 const resp = await fetch(
 `${API_BASE}/x_274351_finance_0_accounts?${params}`,
 { headers: getHeaders() }
 );
 if (!resp.ok) return [];
 const data = await resp.json();
 return data.result || [];
}

export async function fetchTransactions(
 accountId: string,
 fromDate?: string,
 toDate?: string,
 search?: string
): Promise<any[]> {
 const parts = [`account=${accountId}`];
 if (fromDate) parts.push(`timestamp>=${fromDate}`);
 if (toDate) parts.push(`timestamp<=${toDate}`);
 if (search?.trim()) parts.push(`descriptionLIKE${search.trim()}`);
 const query = parts.join("^") + "^ORDERBYDESCtimestamp";

 const params = new URLSearchParams({
 sysparm_display_value: "all",
 sysparm_fields:
 "sys_id,number,timestamp,type,description,amount,balance_after,status",
 sysparm_query: query,
 sysparm_limit: "100",
 });
 const resp = await fetch(
 `${API_BASE}/x_274351_finance_0_txn?${params}`,
 { headers: getHeaders() }
 );
 if (!resp.ok) return [];
 const data = await resp.json();
 return data.result || [];
}
","import React from "react";

const MONTHS = [
 { value: "01", label: "January" }, { value: "02", label: "February" },
 { value: "03", label: "March" }, { value: "04", label: "April" },
 { value: "05", label: "May" }, { value: "06", label: "June" },
 { value: "07", label: "July" }, { value: "08", label: "August" },
 { value: "09", label: "September" },{ value: "10", label: "October" },
 { value: "11", label: "November" }, { value: "12", label: "December" },
];

const YEARS = Array.from({ length: 11 }, (_, i) => String(2020 + i));

interface FilterProps {
 fromMonth: string; fromYear: string;
 toMonth: string; toYear: string;
 searchText: string;
 onFromMonthChange: (v: string) => void;
 onFromYearChange: (v: string) => void;
 onToMonthChange: (v: string) => void;
 onToYearChange: (v: string) => void;
 onSearchChange: (v: string) => void;
 onApply: () => void;
}

export default function TransactionFilters(props: FilterProps) {
 return (
 <div className="txn-filters">
 <div className="txn-filters__row">
 <div className="txn-filters__group">
 <label className="txn-filters__label">From</label>
 <select className="txn-filters__select" value={props.fromMonth}
 onChange={(e) => props.onFromMonthChange(e.target.value)}>
 {MONTHS.map((m) => (
 <option key={m.value} value={m.value}>{m.label}</option>
 ))}
 </select>
 <select className="txn-filters__select txn-filters__select--year"
 value={props.fromYear}
 onChange={(e) => props.onFromYearChange(e.target.value)}>
 {YEARS.map((y) => <option key={y} value={y}>{y}</option>)}
 </select>
 </div>
 <div className="txn-filters__group">
 <label className="txn-filters__label">To</label>
 <select className="txn-filters__select" value={props.toMonth}
 onChange={(e) => props.onToMonthChange(e.target.value)}>
 {MONTHS.map((m) => (
 <option key={m.value} value={m.value}>{m.label}</option>
 ))}
 </select>
 <select className="txn-filters__select txn-filters__select--year"
 value={props.toYear}
 onChange={(e) => props.onToYearChange(e.target.value)}>
 {YEARS.map((y) => <option key={y} value={y}>{y}</option>)}
 </select>
 </div>
 </div>
 <div className="txn-filters__actions">
 <div className="txn-filters__search-wrap">
 <input
 type="text"
 className="txn-filters__input"
 placeholder="Search by description…"
 value={props.searchText}
 onChange={(e) => props.onSearchChange(e.target.value)}
 onKeyDown={(e) => { if (e.key === "Enter") props.onApply(); }}
 />
 </div>
 <button className="txn-filters__btn" type="button" onClick={props.onApply}>
 Apply Filters
 </button>
 </div>
 </div>
 );
}
","import React from "react";

interface Props {
 transactions: any[];
 loading: boolean;
}

export default function TransactionTable({ transactions, loading }: Props) {
 if (loading) {
 return <p className="txn-table__loading">Loading...</p>;
 }
 if (!transactions.length) {
 return <p className="txn-table__empty">No transactions found.</p>;
 }

 return (
 <div className="txn-table__wrapper">
 <table className="txn-table">
 <thead>
 <tr>
 <th>Number</th>
 <th>Date</th>
 <th>Type</th>
 <th>Description</th>
 <th>Amount</th>
 <th>Balance After</th>
 <th>Status</th>
 </tr>
 </thead>
 <tbody>
 {transactions.map((t) => (
 <tr key={t.sys_id.value}>
 <td>{t.number.display_value}</td>
 <td>{t.timestamp.display_value}</td>
 <td>{t.type.display_value}</td>
 <td>{t.description.display_value}</td>
 <td className="txn-table__amount">{t.amount.display_value}</td>
 <td className="txn-table__amount">
 {t.balance_after.display_value}
 </td>
 <td>
 <span
 className={`txn-status txn-status--${t.status.value}`}
 >
 {t.status.display_value}
 </span>
 </td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 );
}
","/* ── Reset ── */
*, *::before, *::after { box-sizing: border-box; }

/* ── Page Layout ── */
.ma-page {
 max-width: 1100px;
 margin: 0 auto;
 padding: 24px 32px;
 font-family: "Source Sans Pro", Arial, sans-serif;
 color: rgb(var(--now-color--text-primary, 22, 27, 33));
}

.ma-page__title {
 font-size: 22px;
 font-weight: 600;
 margin: 0 0 20px;
 color: rgb(var(--now-color--text-primary, 22, 27, 33));
}

.ma-page__msg {
 color: rgb(var(--now-color--text-tertiary, 117, 117, 117));
 font-size: 14px;
 margin: 0;
 padding: 16px 0;
}

/* ── Account Selector ── */
.ma-select-label {
 display: block;
 font-size: 13px;
 font-weight: 600;
 margin-bottom: 6px;
 color: rgb(var(--now-color--text-secondary, 66, 80, 92));
}

.ma-select {
 display: block;
 width: 100%;
 max-width: 520px;
 padding: 10px 14px;
 font-size: 14px;
 font-family: inherit;
 color: rgb(var(--now-color--text-primary, 22, 27, 33));
 background-color: rgb(var(--now-color--background-primary, 255, 255, 255));
 border: 1px solid rgb(var(--now-color--divider-primary, 189, 193, 198));
 border-radius: 4px;
 appearance: auto;
 cursor: pointer;
 margin-bottom: 20px;
}

.ma-select:focus {
 outline: 2px solid rgb(var(--now-color--focus-ring, 0, 128, 163));
 outline-offset: 1px;
}

/* ── Account Details Card ── */
.ma-details {
 display: flex;
 gap: 28px;
 flex-wrap: wrap;
 padding: 14px 20px;
 margin-bottom: 24px;
 background: rgb(var(--now-color--background-secondary, 243, 243, 243));
 border: 1px solid rgb(var(--now-color--divider-secondary, 218, 220, 224));
 border-radius: 6px;
}

.ma-details__item {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.ma-details__label {
 font-size: 11px;
 font-weight: 600;
 text-transform: uppercase;
 letter-spacing: 0.5px;
 color: rgb(var(--now-color--text-tertiary, 117, 117, 117));
}

.ma-details__value {
 font-size: 14px;
 color: rgb(var(--now-color--text-primary, 22, 27, 33));
}

.ma-details__value--bold {
 font-weight: 700;
}

/* ── Badges ── */
.ma-badge {
 display: inline-block;
 padding: 2px 10px;
 border-radius: 12px;
 font-size: 12px;
 font-weight: 600;
}

.ma-badge--active {
 background: rgb(var(--now-color--alert-positive-2, 220, 245, 220));
 color: rgb(var(--now-color--alert-positive-3, 30, 100, 30));
}

.ma-badge--inactive {
 background: rgb(var(--now-color--alert-critical-2, 255, 220, 220));
 color: rgb(var(--now-color--alert-critical-3, 180, 30, 30));
}

/* ── Section Title ── */
.ma-section-title {
 font-size: 17px;
 font-weight: 600;
 margin: 0 0 14px;
 padding-bottom: 8px;
 border-bottom: 1px solid rgb(var(--now-color--divider-secondary, 218, 220, 224));
 color: rgb(var(--now-color--text-primary, 22, 27, 33));
}

/* ── Transaction Filters ── */
.txn-filters {
 margin-bottom: 20px;
 padding: 16px;
 background: rgb(var(--now-color--background-secondary, 243, 243, 243));
 border: 1px solid rgb(var(--now-color--divider-secondary, 218, 220, 224));
 border-radius: 6px;
}

.txn-filters__row {
 display: flex;
 gap: 24px;
 flex-wrap: wrap;
 margin-bottom: 12px;
}

.txn-filters__group {
 display: flex;
 align-items: center;
 gap: 8px;
}

.txn-filters__label {
 font-weight: 600;
 font-size: 13px;
 min-width: 36px;
 color: rgb(var(--now-color--text-secondary, 66, 80, 92));
}

.txn-filters__select {
 padding: 8px 10px;
 font-size: 13px;
 font-family: inherit;
 color: rgb(var(--now-color--text-primary, 22, 27, 33));
 background: rgb(var(--now-color--background-primary, 255, 255, 255));
 border: 1px solid rgb(var(--now-color--divider-primary, 189, 193, 198));
 border-radius: 4px;
 appearance: auto;
 cursor: pointer;
 min-width: 120px;
}

.txn-filters__select--year {
 min-width: 80px;
}

.txn-filters__select:focus {
 outline: 2px solid rgb(var(--now-color--focus-ring, 0, 128, 163));
 outline-offset: 1px;
}

.txn-filters__actions {
 display: flex;
 align-items: center;
 gap: 12px;
 flex-wrap: wrap;
}

.txn-filters__search-wrap {
 flex: 1;
 min-width: 200px;
 max-width: 400px;
}

.txn-filters__input {
 display: block;
 width: 100%;
 padding: 8px 12px;
 font-size: 13px;
 font-family: inherit;
 color: rgb(var(--now-color--text-primary, 22, 27, 33));
 background: rgb(var(--now-color--background-primary, 255, 255, 255));
 border: 1px solid rgb(var(--now-color--divider-primary, 189, 193, 198));
 border-radius: 4px;
}

.txn-filters__input:focus {
 outline: 2px solid rgb(var(--now-color--focus-ring, 0, 128, 163));
 outline-offset: 1px;
}

.txn-filters__input::placeholder {
 color: rgb(var(--now-color--text-tertiary, 117, 117, 117));
}

.txn-filters__btn {
 padding: 8px 20px;
 font-size: 13px;
 font-weight: 600;
 font-family: inherit;
 color: #fff;
 background: rgb(var(--now-color--primary-1, 0, 128, 163));
 border: none;
 border-radius: 4px;
 cursor: pointer;
 white-space: nowrap;
}

.txn-filters__btn:hover {
 background: rgb(var(--now-color--primary-2, 0, 100, 130));
}

.txn-filters__btn:focus-visible {
 outline: 2px solid rgb(var(--now-color--focus-ring, 0, 128, 163));
 outline-offset: 2px;
}

/* ── Transaction Table ── */
.txn-table__loading,
.txn-table__empty {
 text-align: center;
 padding: 32px 16px;
 color: rgb(var(--now-color--text-tertiary, 117, 117, 117));
 font-size: 14px;
 margin: 0;
}

.txn-table__wrapper {
 overflow-x: auto;
 border: 1px solid rgb(var(--now-color--divider-secondary, 218, 220, 224));
 border-radius: 6px;
}

.txn-table {
 width: 100%;
 border-collapse: collapse;
 font-size: 13px;
}

.txn-table thead th {
 text-align: left;
 padding: 10px 12px;
 font-weight: 600;
 font-size: 12px;
 text-transform: uppercase;
 letter-spacing: 0.4px;
 color: rgb(var(--now-color--text-secondary, 66, 80, 92));
 background: rgb(var(--now-color--background-tertiary, 227, 229, 232));
 border-bottom: 2px solid rgb(var(--now-color--divider-primary, 189, 193, 198));
}

.txn-table tbody td {
 padding: 10px 12px;
 border-bottom: 1px solid rgb(var(--now-color--divider-secondary, 218, 220, 224));
 color: rgb(var(--now-color--text-primary, 22, 27, 33));
}

.txn-table tbody tr:hover {
 background: rgb(var(--now-color--background-secondary, 243, 243, 243));
}

.txn-table__amount {
 text-align: right;
 font-variant-numeric: tabular-nums;
}

/* ── Transaction Status Badges ── */
.txn-status {
 display: inline-block;
 padding: 2px 10px;
 border-radius: 12px;
 font-size: 11px;
 font-weight: 600;
 white-space: nowrap;
}

.txn-status--complete,
.txn-status--completed {
 background: rgb(var(--now-color--alert-positive-2, 220, 245, 220));
 color: rgb(var(--now-color--alert-positive-3, 30, 100, 30));
}

.txn-status--pending {
 background: rgb(var(--now-color--alert-warning-2, 255, 245, 210));
 color: rgb(var(--now-color--alert-warning-3, 140, 100, 10));
}

.txn-status--failed {
 background: rgb(var(--now-color--alert-critical-2, 255, 220, 220));
 color: rgb(var(--now-color--alert-critical-3, 180, 30, 30));
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useEffect } from "react";
import { fetchAccounts, fetchTransactions } from "./api";
import TransactionFilters from "./TransactionFilters";
import TransactionTable from "./TransactionTable";
import "./app.css";

const now = new Date();
const CUR_MONTH = String(now.getMonth() + 1).padStart(2, "0");
const CUR_YEAR = String(now.getFullYear());

export default function App() {
 const [accounts, setAccounts] = useState<any[]>([]);
 const [selectedId, setSelectedId] = useState("");
 const [transactions, setTransactions] = useState<any[]>([]);
 const [acctLoading, setAcctLoading] = useState(true);
 const [txnLoading, setTxnLoading] = useState(false);
 const [fromMonth, setFromMonth] = useState(CUR_MONTH);
 const [fromYear, setFromYear] = useState(CUR_YEAR);
 const [toMonth, setToMonth] = useState(CUR_MONTH);
 const [toYear, setToYear] = useState(CUR_YEAR);
 const [search, setSearch] = useState("");

 useEffect(() => {
 document.title = "My Accounts";
 fetchAccounts().then((data) => {
 setAccounts(data);
 setAcctLoading(false);
 });
 }, []);

 const loadTxns = async (
 acctId: string, fm: string, fy: string,
 tm: string, ty: string, s: string
 ) => {
 if (!acctId) return;
 setTxnLoading(true);
 const lastDay = new Date(parseInt(ty), parseInt(tm), 0).getDate();
 const from = `${fy}-${fm}-01`;
 const to = `${ty}-${tm}-${String(lastDay).padStart(2, "0")}`;
 const data = await fetchTransactions(acctId, from, to, s);
 setTransactions(data);
 setTxnLoading(false);
 };

 const onAccountChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
 const id = e.target.value;
 setSelectedId(id);
 setTransactions([]);
 if (id) loadTxns(id, fromMonth, fromYear, toMonth, toYear, search);
 };

 const onApply = () =>
 loadTxns(selectedId, fromMonth, fromYear, toMonth, toYear, search);

 const selectedAcct = accounts.find((a) => a.sys_id.value === selectedId);

 return (
 <div className="ma-page">
 <h1 className="ma-page__title">My Accounts</h1>

 {acctLoading ? (
 <p className="ma-page__msg">Loading accounts…</p>
 ) : accounts.length === 0 ? (
 <p className="ma-page__msg">No accounts found.</p>
 ) : (
 <>
 <label className="ma-select-label" htmlFor="acct-select">
 Select Account
 </label>
 <select
 id="acct-select"
 className="ma-select"
 value={selectedId}
 onChange={onAccountChange}
 >
 <option value="">-- Choose an account --</option>
 {accounts.map((a) => (
 <option key={a.sys_id.value} value={a.sys_id.value}>
 {a.number.display_value} — {a.account_type.display_value}
 {" "}(Balance: {a.balance.display_value})
 </option>
 ))}
 </select>

 {selectedAcct && (
 <div className="ma-details">
 <div className="ma-details__item">
 <span className="ma-details__label">Account</span>
 <span className="ma-details__value">
 {selectedAcct.number.display_value}
 </span>
 </div>
 <div className="ma-details__item">
 <span className="ma-details__label">Type</span>
 <span className="ma-details__value">
 {selectedAcct.account_type.display_value}
 </span>
 </div>
 <div className="ma-details__item">
 <span className="ma-details__label">Balance</span>
 <span className="ma-details__value ma-details__value--bold">
 {selectedAcct.balance.display_value}
 </span>
 </div>
 <div className="ma-details__item">
 <span className="ma-details__label">Status</span>
 <span className={`ma-badge ${
 selectedAcct.active.value === "true" || selectedAcct.active.value === "1"
 ? "ma-badge--active" : "ma-badge--inactive"
 }`}>
 {selectedAcct.active.value === "true" || selectedAcct.active.value === "1"
 ? "Active" : "Inactive"}
 </span>
 </div>
 </div>
 )}

 {selectedId && (
 <>
 <h2 className="ma-section-title">Transactions</h2>
 <TransactionFilters
 fromMonth={fromMonth} fromYear={fromYear}
 toMonth={toMonth} toYear={toYear}
 searchText={search}
 onFromMonthChange={setFromMonth}
 onFromYearChange={setFromYear}
 onToMonthChange={setToMonth}
 onToYearChange={setToYear}
 onSearchChange={setSearch}
 onApply={onApply}
 />
 <TransactionTable
 transactions={transactions}
 loading={txnLoading}
 />
 </>
 )}
 </>
 )}
 </div>
 );
}
